def main():
    by_name = {g["nome"]: g for g in GRAFICHE}
    voci, agganci = [], []
    for data, key, nome, alt, hook, cap in POST:
        g = by_name[nome]
        n = len(g.get("slide") or [g])
        files = [f"{nome}.png"] if n == 1 else [f"{nome}_{i}.png" for i in range(1, n + 1)]
        for f in files:
            assert (ROOT / "dicembre" / f).exists(), f
        imgs = [{"url": RAW + f, "altText": alt if i == 0 else f"{alt} Slide {i + 1} di {n}."} for i, f in enumerate(files)]
        for ch in ("li", "ig", "tt"):
            cid, svc, ora = CH[ch]
            t = cap[ch]
            assert "#tassareimilionari" in t and "@einaudieditore" in t, (key, ch)
            v = {"key": f"dic-{key}-{ch}", "channelId": cid, "service": svc,
                 "dueAt": f"{data}T{ora}:00+01:00", "text": t, "images": imgs}
            if svc == "instagram":
                v["instagramType"] = "post"
            voci.append(v)
        if hook:
            agganci.append({"key": f"dic-{key}", "data": data, "image": RAW + files[0], "alt": alt, "hook": hook})
    for data, key, url, text in REEL_TT:
        voci.append({"key": f"reel-{key}-tt", "channelId": TIKTOK, "service": "tiktok",
                     "dueAt": f"{data}T20:30:00+01:00", "text": text, "video": url})
    voci.sort(key=lambda v: v["dueAt"])
    out = {"buffer": voci, "lapidari_da_riciclare": agganci}
    (ROOT / "dicembre" / "coda_dicembre.json").write_text(json.dumps(out, ensure_ascii=False, indent=1), encoding="utf-8")
    # accoda anche alla lista letta dal rabbocco serale (ottobre/coda_buffer.json)
    coda = ROOT / "ottobre" / "coda_buffer.json"
    old = json.loads(coda.read_text(encoding="utf-8"))
    old = [v for v in old if not v["key"].startswith(("dic-", "reel-"))] + voci
    coda.write_text(json.dumps(old, ensure_ascii=False, indent=1), encoding="utf-8")
    print(len(voci), "voci Buffer;", len(agganci), "lapidari da riciclare")


if __name__ == "__main__":
    main()
